function L(en,bn){return lang==="bn"?bn:en}
function durOf(dep,arr){var a=dep.split(":"),b=arr.split(":");var d=(+b[0])*60+(+b[1])-((+a[0])*60+(+a[1]));if(d<=0)d+=1440;return d}
function fmtDur(m){var h=Math.floor(m/60),r=m%60;return h+"h"+(r?" "+r+"m":"")}
function trainMinFare(x){return Math.min.apply(null,x.fares.map(function(f){return f[1]}))}
function trainCard(x){return "<article class='card trip'><div class='trip-head'><div><strong style='font-size:1.08rem'>🚆 "+x.n+"</strong> <span class='chip'>"+(lang==="bn"?x.bn:"Train "+x.no)+"</span> <span class='chip'>Sample</span><div style='color:var(--muted)'>"+x.from+" → "+x.to+" · "+x.dep+" → "+x.arr+" ("+fmtDur(durOf(x.dep,x.arr))+") · "+x.day+"</div><div style='margin-top:5px'>"+x.stops.map(function(s){return "<span class='chip'>"+s+"</span>"}).join(" ")+"</div></div><div style='text-align:right'><div class='price'>৳"+trainMinFare(x)+"</div><div style='color:var(--muted);font-size:.85rem'>"+L("from, per seat (sample fare)","থেকে, প্রতি আসন (স্যাম্পল ভাড়া)")+"</div></div></div><div style='margin-top:8px'>"+x.fares.map(function(f){return "<span class='chip'>"+f[0]+": ৳"+f[1]+"</span>"}).join(" ")+"</div></article>"}
function busCardU(x){return "<article class='card trip'><div class='trip-head'><div><strong style='font-size:1.08rem'>"+x.op+"</strong> <span class='chip'>"+x.type+"</span> <span class='chip'>Sample</span><div style='color:var(--muted)'>"+x.from+" → "+x.to+" · "+x.dep+" → "+x.arr+" ("+fmtDur(durOf(x.dep,x.arr))+")<br>"+L("Boarding","বোর্ডিং")+": "+x.board+" · "+L("Dropping","ড্রপিং")+": "+x.drop+"</div></div><div style='text-align:right'><div class='price'>৳"+x.fare+"</div><div style='color:var(--muted);font-size:.85rem'>"+L("per seat (sample fare)","প্রতি আসন (স্যাম্পল ভাড়া)")+"</div><button class='btn small' onclick='bookFromPlace("+x.id+")'>"+L("Select Seats","আসন বেছে নিন")+"</button></div></div></article>"}
function localCardU(r,q){return "<article class='card' style='padding:16px;margin-bottom:12px'><div class='trip-head'><div><strong style='font-size:1.05rem'>"+r.name+"</strong> — "+r.from+" → "+r.to+"<div style='color:var(--muted);font-size:.9rem'>Operator: "+r.op+" · Fare: "+r.fare+"</div></div>"+(r.verified?"<span class='badge b-ver'>Verified (sample)</span>":"<span class='badge b-unv'>Unverified / user-submitted</span>")+"</div><p style='margin:8px 0 0'>"+r.stops.map(function(s){var hit=q&&s[0].toLowerCase().indexOf(q)>=0;return "<span class='chip'"+(hit?" style='background:var(--green);color:#fff;border-color:var(--green)'":"")+">"+s[0]+"</span>"}).join(" ")+"</p><p style='margin-top:10px'><button class='btn small' onclick='showOnMap("+r.id+")'>"+L("View on map","ম্যাপে দেখুন")+"</button></p></article>"}
function fillTrainSelects(){var cities=[];TRAINS.forEach(function(x){if(cities.indexOf(x.from)<0)cities.push(x.from);if(cities.indexOf(x.to)<0)cities.push(x.to)});cities.sort();
var all=L("All cities","সব শহর");
document.getElementById("trFrom").innerHTML="<option value=''>"+all+"</option>"+cities.map(function(c){return "<option>"+c+"</option>"}).join("");
document.getElementById("trTo").innerHTML="<option value=''>"+all+"</option>"+cities.map(function(c){return "<option>"+c+"</option>"}).join("")}
function renderTrains(){var f=document.getElementById("trFrom").value,tt=document.getElementById("trTo").value,q=(document.getElementById("trQ").value||"").trim().toLowerCase();
var list=TRAINS.filter(function(x){if(f&&x.from!==f)return false;if(tt&&x.to!==tt)return false;if(q&&(x.n+" "+x.bn+" "+x.no+" "+x.from+" "+x.to+" "+x.stops.join(" ")).toLowerCase().indexOf(q)<0)return false;return true});
var box=document.getElementById("trainList");
if(!list.length){box.innerHTML="<div class='card' style='padding:26px;text-align:center'><h3>"+L("No sample trains found","কোনো স্যাম্পল ট্রেন পাওয়া যায়নি")+"</h3><p style='color:var(--muted)'>"+L("Try Dhaka → Chattogram or Dhaka → Sylhet, or clear the search box.","ঢাকা → চট্টগ্রাম অথবা ঢাকা → সিলেট চেষ্টা করুন, অথবা সার্চ বক্স খালি করুন।")+"</p></div>";return}
box.innerHTML=list.map(trainCard).join("")}
var CITY_ALIAS=[["Dhaka",["ঢাকা","dhaka"]],["Chattogram",["চট্টগ্রাম","chattogram","chittagong","ctg"]],["Cox's Bazar",["cox's bazar","coxs bazar","cox bazar","কক্সবাজার"]],["Sylhet",["সিলেট","sylhet"]],["Khulna",["খুলনা","khulna"]],["Rajshahi",["রাজশাহী","rajshahi"]],["Barishal",["বরিশাল","barishal","barisal"]],["Cumilla",["কুমিল্লা","cumilla","comilla"]],["Panchagarh",["পঞ্চগড়","panchagarh"]],["Lalmonirhat",["লালমনিরহাট","lalmonirhat"]],["Chilahati",["চিলাহাটি","chilahati"]],["Mymensingh",["ময়মনসিংহ","mymensingh"]],["Rangpur",["রংপুর","rangpur"]],["Dinajpur",["দিনাজপুর","dinajpur"]],["Jashore",["যশোর","jashore","jessore"]],["Bogura",["বগুড়া","bogura","bogra"]],["Feni",["ফেনী","feni"]],["Tangail",["টাঙ্গাইল","tangail"]]];
function parseTravelQuery(q){var s=" "+q.toLowerCase()+" ";var pairs=[];
CITY_ALIAS.forEach(function(c){c[1].forEach(function(k){pairs.push([c[0],k])})});
pairs.sort(function(a,b){return b[1].length-a[1].length});
var found={};
pairs.forEach(function(p){if(found[p[0]]!==undefined)return;var i=s.indexOf(p[1]);if(i>=0)found[p[0]]=i});
var arr=Object.keys(found).map(function(c){return{city:c,idx:found[c]}}).sort(function(a,b){return a.idx-b.idx});
if(arr.length>=2)return{type:"route",from:arr[0].city,to:arr[1].city};
if(arr.length===1)return{type:"place",city:arr[0].city};
return null}
function recText(from,to,buses,trains){var opts=[];
buses.forEach(function(x){opts.push({kind:L("bus","বাস"),label:x.op,dur:durOf(x.dep,x.arr),fare:x.fare,dep:x.dep})});
trains.forEach(function(x){opts.push({kind:L("train","ট্রেন"),label:x.n,dur:durOf(x.dep,x.arr),fare:trainMinFare(x),dep:x.dep})});
if(!opts.length)return "";
var fastest=opts.slice().sort(function(a,b){return a.dur-b.dur})[0];
var cheapest=opts.slice().sort(function(a,b){return a.fare-b.fare})[0];
var s="<div class='rec' style='margin-bottom:14px'><strong>"+L("Best way: ","সেরা উপায়: ")+from+" → "+to+"</strong><br>";
s+=L("Fastest: take the ","সবচেয়ে দ্রুত: ")+fastest.kind+" <strong>"+fastest.label+"</strong> — "+L("departs ","ছাড়ে ")+fastest.dep+", "+L("about ","প্রায় ")+fmtDur(fastest.dur)+", "+L("fares from ","ভাড়া ")+"৳"+fastest.fare+L("."," থেকে।");
s+="<br>"+L("Cheapest: ","সবচেয়ে সস্তা: ")+cheapest.kind+" <strong>"+cheapest.label+"</strong> — "+L("departs ","ছাড়ে ")+cheapest.dep+", "+L("about ","প্রায় ")+fmtDur(cheapest.dur)+", ৳"+cheapest.fare+L(".","।");
if(!trains.length)s+="<br>"+L("No sample train runs this route in the demo data — the buses below are your options.","ডেমো ডেটায় এই রুটে কোনো স্যাম্পল ট্রেন নেই — নিচের বাসগুলোই আপনার অপশন।");
if(!buses.length)s+="<br>"+L("No sample bus runs this route in the demo data — the trains below are your options.","ডেমো ডেটায় এই রুটে কোনো স্যাম্পল বাস নেই — নিচের ট্রেনগুলোই আপনার অপশন।");
s+="<br><span style='font-size:.88rem'>"+L("Recommendation from sample demo data — check the full list below.","স্যাম্পল ডেমো ডেটা থেকে পরামর্শ — নিচে পুরো তালিকা দেখুন।")+"</span></div>";
return s}
function routeResults(from,to){var buses=TRIPS.filter(function(x){return x.from===from&&x.to===to});
var trains=TRAINS.filter(function(x){return x.from===from&&x.to===to});
var html="<h3 style='margin:2px 0 10px'>"+from+" → "+to+"</h3>";
if(!buses.length&&!trains.length){var revB=TRIPS.filter(function(x){return x.from===to&&x.to===from}).length,revT=TRAINS.filter(function(x){return x.from===to&&x.to===from}).length;
html+="<div class='card' style='padding:22px;text-align:center'><h3>"+L("No direct sample bus or train for this route","এই রুটে সরাসরি কোনো স্যাম্পল বাস বা ট্রেন নেই")+"</h3><p style='color:var(--muted)'>"+L("This demo dataset has no direct "+from+" → "+to+" service.","এই ডেমো ডেটাসেটে "+from+" → "+to+" সরাসরি সার্ভিস নেই।")+(revB||revT?L(" The reverse direction ("+to+" → "+from+") does exist — try swapping."," উল্টো দিক ("+to+" → "+from+") আছে — অদলবদল করে চেষ্টা করুন।"):"")+"</p></div>";return html}
html+=recText(from,to,buses,trains);
if(buses.length)html+="<h3 style='margin:4px 0 10px'>🚌 "+L("Buses","বাস")+" ("+buses.length+")</h3>"+buses.map(busCardU).join("");
if(trains.length)html+="<h3 style='margin:18px 0 10px'>🚆 "+L("Trains","ট্রেন")+" ("+trains.length+")</h3>"+trains.map(trainCard).join("");
return html}
function placeResults(city,rawQ){var q=(city||rawQ).toLowerCase();
var buses=TRIPS.filter(function(x){return (x.from+" "+x.to+" "+x.board+" "+x.drop).toLowerCase().indexOf(q)>=0});
var trains=TRAINS.filter(function(x){return (x.n+" "+x.from+" "+x.to+" "+x.stops.join(" ")).toLowerCase().indexOf(q)>=0});
var locals=LOCAL.filter(function(r){return r.from.toLowerCase().indexOf(q)>=0||r.to.toLowerCase().indexOf(q)>=0||r.stops.some(function(s){return s[0].toLowerCase().indexOf(q)>=0})});
var label=city||rawQ;
if(!buses.length&&!trains.length&&!locals.length){return "<div class='card' style='padding:22px;text-align:center'><h3>"+L("Nothing found for “"+label+"”","“"+label+"” এর জন্য কিছু পাওয়া যায়নি")+"</h3><p style='color:var(--muted)'>"+L("No sample bus, train or Dhaka local route matches. Try a city like Dhaka, Chattogram, Sylhet, or a Dhaka stop like Farmgate or Gulistan.","কোনো স্যাম্পল বাস, ট্রেন বা ঢাকা লোকাল রুট মিলছে না। ঢাকা, চট্টগ্রাম, সিলেটের মতো শহর, অথবা ফার্মগেট বা গুলিস্তানের মতো ঢাকার স্টপ চেষ্টা করুন।")+"</p></div>"}
var html="<h3 style='margin:2px 0 10px'>"+L("Buses & trains for “"+label+"”","“"+label+"” এর বাস ও ট্রেন")+"</h3>";
if(buses.length)html+="<h3 style='margin:4px 0 10px'>🚌 "+L("Intercity buses","আন্তঃনগর বাস")+" ("+buses.length+")</h3>"+buses.map(busCardU).join("");
if(trains.length)html+="<h3 style='margin:18px 0 10px'>🚆 "+L("Trains","ট্রেন")+" ("+trains.length+")</h3>"+trains.map(trainCard).join("");
if(locals.length)html+="<h3 style='margin:18px 0 10px'>🚏 "+L("Dhaka local routes","ঢাকা লোকাল রুট")+" ("+locals.length+")</h3>"+locals.map(function(r){return localCardU(r,q)}).join("");
return html}
function runUniversal(){var q=document.getElementById("uQ").value.trim();hideSug();var box=document.getElementById("uResults");if(q&&typeof noteRecent==="function")noteRecent(q);
if(!q){box.innerHTML="";return}
var p=parseTravelQuery(q);
if(p&&p.type==="route")box.innerHTML=routeResults(p.from,p.to);
else if(p&&p.type==="place")box.innerHTML=placeResults(p.city,q);
else box.innerHTML=placeResults(null,q);
box.scrollIntoView({block:"nearest"})}
var UPLACES=[];
function buildUPlaces(){var seen={},out=[];function add(x){if(!x)return;var k=x.toLowerCase();if(!seen[k]){seen[k]=1;out.push(x)}}
CITY_ALIAS.forEach(function(c){add(c[0])});
TRIPS.forEach(function(x){add(x.board.replace(/ Counter$/,""));x.drop.split(",").forEach(function(d){add(d.trim())})});
LOCAL.forEach(function(r){r.stops.forEach(function(s){add(s[0])})});
TRAINS.forEach(function(x){x.stops.forEach(function(s){add(s)});add(x.n)});
UPLACES=out.sort(function(a,b){return a.localeCompare(b)})}
function hideSug(){document.getElementById("uSug").style.display="none"}
function uSuggest(){var q=document.getElementById("uQ").value.trim().toLowerCase(),sug=document.getElementById("uSug");
if(q.length<2){hideSug();return}
var hits=UPLACES.filter(function(p){return p.toLowerCase().indexOf(q)>=0}).slice(0,8);
if(!hits.length){hideSug();return}
sug.innerHTML=hits.map(function(p){return "<button type='button' role='option' onclick=\"uPick('"+p.replace(/'/g,"\\'")+"')\">"+p+"</button>"}).join("");
sug.style.display="block"}
function uPick(v){document.getElementById("uQ").value=v;runUniversal()}
function uExample(btn){document.getElementById("uQ").value=btn.textContent.trim();runUniversal()}
document.addEventListener("click",function(e){var b=document.querySelector(".usearch-box");if(b&&!b.contains(e.target))hideSug()});
