var RATINGS={};
function seedRating(key){if(RATINGS[key])return RATINGS[key];var h=0;for(var i=0;i<key.length;i++)h=(h*31+key.charCodeAt(i))%997;var avg=Math.round((3.6+(h%14)/10)*10)/10;if(avg>4.9)avg=4.9;RATINGS[key]={avg:avg,count:40+(h%160),mine:0,review:"",reported:false};return RATINGS[key]}
function starsHtml(avg){var s="";for(var i=1;i<=5;i++)s+="<span style='color:"+(i<=Math.round(avg)?"#e8a33d":"var(--line)")+"'>★</span>";return "<span class='stars' aria-label='"+avg+" / 5'>"+s+"</span>"}
function ratingLine(key){var r=seedRating(key);return starsHtml(r.avg)+" <strong>"+r.avg.toFixed(1)+"</strong> <span style='color:var(--muted);font-size:.85rem'>("+r.count+" "+L("sample ratings","স্যাম্পল রেটিং")+")</span>"}
function svcByKey(k){return SERVICES.filter(function(s){return s.key===k})[0]}
var CATMETA=[["all","🌐","All"],["bus","🚌","Bus"],["train","🚆","Train"],["launch","🚤","Launch"],["bike","🏍️","Bike"],["car","🚗","Private Car"]];
var catType="all";
var CATBANNER={all:["assets/placeholder.svg","Bangladesh intercity bus on a highway"],bus:["assets/placeholder.svg","Bangladesh intercity bus on a highway"],train:["assets/placeholder.svg","A Bangladesh Railway train at a station"],launch:["assets/placeholder.svg","Boats at the floating guava market, Barishal region"],bike:["assets/placeholder.svg","Lalbagh Fort, Dhaka — bike rides operate across the city"],car:["assets/placeholder.svg","Cox's Bazar Marine Drive road, Chattogram Division"]};
function goCat(tp){catType=tp;var b=document.getElementById("catBanner");if(b&&CATBANNER[tp]){b.style.display="block";b.src=CATBANNER[tp][0];b.alt=CATBANNER[tp][1]}go("services")}
function svcCard(s){return "<article class='card trip'><div class='trip-head'><div><strong style='font-size:1.06rem'>"+s.icon+" "+esc(s.name)+"</strong> <span class='chip'>Sample</span><div style='color:var(--muted)'>"+esc(s.from)+" → "+esc(s.to)+" · "+s.dep+(s.arr&&s.arr!=="—"?" → "+s.arr:"")+(s.dur?" · "+fmtDur(s.dur)+(s.localId?" "+L("(approx.)","(আনুমানিক)"):""):"")+"</div><div style='margin-top:3px'>"+ratingLine(s.key)+"</div></div><div style='text-align:right'><div class='price'>"+s.fareLabel+"</div><div style='color:var(--muted);font-size:.85rem'>"+L("sample fare","স্যাম্পল ভাড়া")+"</div></div></div><p style='display:flex;gap:8px;flex-wrap:wrap;margin:10px 0 0'><button class='btn small' onclick=\"openService('"+s.key+"')\">"+L("Details & rate","বিস্তারিত ও রেটিং")+"</button><button class='btn small ghost' onclick=\"viewServiceMap('"+s.key+"')\">"+L("View on map","ম্যাপে দেখুন")+"</button>"+(s.tripId?"<button class='btn small' onclick='bookFromPlace("+s.tripId+")'>"+L("Select Seats","আসন বেছে নিন")+"</button>":"")+"</p></article>"}
function renderCats(){var tabs=document.getElementById("catTabs");if(tabs)tabs.innerHTML=CATMETA.map(function(c){var n=c[0]==="all"?SERVICES.length:SERVICES.filter(function(s){return s.type===c[0]}).length;return "<button class='"+(catType===c[0]?"on":"")+"' onclick=\"goCat('"+c[0]+"')\">"+c[1]+" "+L(c[2],c[0]==="all"?"সব":c[0]==="bus"?"বাস":c[0]==="train"?"ট্রেন":c[0]==="launch"?"লঞ্চ":c[0]==="bike"?"বাইক":"প্রাইভেট কার")+" ("+n+")</button>"}).join("");
var q=(document.getElementById("catQ")?document.getElementById("catQ").value:"").trim().toLowerCase();
var list=SERVICES.filter(function(s){if(catType!=="all"&&s.type!==catType)return false;if(q&&(s.name+" "+s.from+" "+s.to).toLowerCase().indexOf(q)<0)return false;return true});
var box=document.getElementById("catList");if(!box)return;
if(!list.length){box.innerHTML="<div class='card' style='padding:22px;text-align:center'><h3>"+L("No sample services found","কোনো স্যাম্পল সার্ভিস পাওয়া যায়নি")+"</h3><p style='color:var(--muted)'>"+L("Try another category or clear the name search.","অন্য ক্যাটাগরি চেষ্টা করুন অথবা নামের সার্চ খালি করুন।")+"</p></div>";return}
box.innerHTML=list.map(svcCard).join("")}
var curSvc=null,starPick=0,editingRating=false;
function openService(key){curSvc=svcByKey(key);starPick=seedRating(key).mine||0;editingRating=false;renderDetail();go("detail")}
function pickStar(n){starPick=n;renderDetail()}
function renderDetail(){var s=curSvc;if(!s)return;var r=seedRating(s.key);var box=document.getElementById("detailBox");
var canRate=!r.mine||editingRating;
var starBtns="";for(var i=1;i<=5;i++)starBtns+="<button type='button' class='star-btn"+(i<=starPick?" on":"")+"' onclick='pickStar("+i+")' aria-label='"+i+" star'>★</button>";
box.innerHTML="<article class='card' style='padding:18px'><div class='trip-head'><div><strong style='font-size:1.25rem'>"+s.icon+" "+esc(s.name)+"</strong> <span class='chip'>"+s.type+"</span> <span class='chip'>Sample data</span><div style='color:var(--muted)'>"+esc(s.from)+" → "+esc(s.to)+"</div><div style='margin-top:4px'>"+ratingLine(s.key)+"</div></div><div style='text-align:right'><div class='price'>"+s.fareLabel+"</div><div style='color:var(--muted);font-size:.85rem'>"+L("sample fare","স্যাম্পল ভাড়া")+"</div></div></div>"
+"<dl class='kv' style='margin-top:14px'><dt>"+L("Departure","ছাড়ে")+"</dt><dd>"+s.dep+"</dd><dt>"+L("Arrival","পৌঁছায়")+"</dt><dd>"+s.arr+"</dd><dt>"+L("Journey time","যাত্রার সময়")+"</dt><dd>"+(s.dur?fmtDur(s.dur)+(s.localId?" "+L("(approx., sample)","(আনুমানিক, স্যাম্পল)"):" "+L("(sample)","(স্যাম্পল)")):L("Depends on route","রুট অনুযায়ী"))+"</dd><dt>"+L("Transfers","ট্রান্সফার")+"</dt><dd>"+s.transfers+"</dd></dl>"
+"<h3>"+L("Stops / points","স্টপ / পয়েন্ট")+"</h3><p>"+s.stops.map(function(x){return "<span class='chip'>"+esc(x)+"</span>"}).join(" ")+"</p>"
+(s.classes?"<h3>"+L("Fare by class (sample)","শ্রেণি অনুযায়ী ভাড়া (স্যাম্পল)")+"</h3><p>"+s.classes.map(function(f){return "<span class='chip'>"+esc(f[0])+": ৳"+f[1]+"</span>"}).join(" ")+"</p>":"")
+"<h3>"+L("Facilities (sample)","সুবিধা (স্যাম্পল)")+"</h3><p>"+s.fac.map(function(f){return "<span class='chip'>"+esc(f)+"</span>"}).join(" ")+"</p>"
+"<p style='display:flex;gap:8px;flex-wrap:wrap'><button class='btn small' onclick=\"viewServiceMap('"+s.key+"')\">"+L("View Route","রুট দেখুন")+"</button><a class='btn small ghost' style='text-decoration:none' target='_blank' rel='noopener' href='https://www.google.com/maps/dir/?api=1&origin="+encodeURIComponent(s.from)+"&destination="+encodeURIComponent(s.to)+"'>"+L("Get Directions ↗","দিকনির্দেশনা ↗")+"</a>"+(s.tripId?"<button class='btn small' onclick='bookFromPlace("+s.tripId+")'>"+L("Select Seats","আসন বেছে নিন")+"</button>":"")+"</p>"
+(s.type==="train"||s.type==="launch"?"<p class='notice'>"+L("Tickets for this service are not sold in this demo — buy at the station/terminal counter or the official e-ticket service.","এই ডেমোতে এই সার্ভিসের টিকিট বিক্রি হয় না — স্টেশন/টার্মিনাল কাউন্টার বা অফিসিয়াল ই-টিকিট সার্ভিস থেকে কিনুন।")+"</p>":"")
+"<hr style='border:0;border-top:1px solid var(--line);margin:16px 0'><h3>"+L("Rate this service","এই সার্ভিসকে রেট করুন")+"</h3>"
+(r.mine&&!editingRating?"<p>"+L("You rated this service","আপনি এই সার্ভিসকে রেট করেছেন")+" <strong>"+r.mine+" ★</strong>"+(r.review?" — “"+esc(r.review)+"”":"")+"</p><p style='display:flex;gap:8px;flex-wrap:wrap'><button class='btn small ghost' onclick='editRating()'>"+L("Edit my rating","আমার রেটিং সম্পাদনা")+"</button><button class='btn small ghost' onclick='reportReview()'>"+L("Report","রিপোর্ট")+"</button></p><div id='rateOut'></div>"
:"<div role='radiogroup' aria-label='Your rating'>"+starBtns+"</div><label for='revTxt'>"+L("Review (optional)","রিভিউ (ঐচ্ছিক)")+"</label><textarea id='revTxt' rows='2' placeholder='"+L("How was the journey?","যাত্রা কেমন ছিল?")+"'>"+esc(r.review||"")+"</textarea><div id='rateOut' style='margin-top:8px'></div><button class='btn small' style='margin-top:8px' onclick='submitRating()'>"+L("Submit rating","রেটিং জমা দিন")+"</button><p style='color:var(--muted);font-size:.85rem'>"+L("One rating per service per session in this prototype; ratings are sample-session data only.","এই প্রোটোটাইপে প্রতি সেশনে একটি সার্ভিসে একবারই রেট করা যায়; রেটিং শুধু স্যাম্পল-সেশন ডেটা।")+"</p>")
+"</article>"}
function editRating(){editingRating=true;starPick=seedRating(curSvc.key).mine;renderDetail()}
function reportReview(){var o=document.getElementById("rateOut");if(o)o.innerHTML="<div class='success'>"+L("Reported (simulated). Nothing was sent anywhere.","রিপোর্ট করা হয়েছে (সিমুলেটেড)। কোথাও কিছু পাঠানো হয়নি।")+"</div>"}
function submitRating(){var r=seedRating(curSvc.key);var out=document.getElementById("rateOut");
if(!starPick){out.innerHTML="<div class='err'>"+L("Please tap 1–5 stars first.","আগে ১–৫ তারায় ট্যাপ করুন।")+"</div>";return}
var txt=document.getElementById("revTxt").value.trim();
if(r.mine&&!editingRating){out.innerHTML="<div class='err'>"+L("You already rated this service in this session.","এই সেশনে আপনি ইতিমধ্যে এই সার্ভিসকে রেট করেছেন।")+"</div>";return}
if(r.mine){r.avg=Math.round(((r.avg*r.count-r.mine+starPick)/r.count)*10)/10}
else{r.avg=Math.round(((r.avg*r.count+starPick)/(r.count+1))*10)/10;r.count+=1}
r.mine=starPick;r.review=txt;editingRating=false;renderDetail();
var o2=document.getElementById("rateOut");if(o2)o2.innerHTML="<div class='success'>"+L("Thanks! The average rating above has been updated.","ধন্যবাদ! উপরের গড় রেটিং আপডেট হয়েছে।")+"</div>"}
function cityListAll(){var seen={},out=[];SERVICES.forEach(function(s){[s.cf,s.ct].forEach(function(c){if(c&&!seen[c]){seen[c]=1;out.push(c)}})});CITIES.forEach(function(c){if(!seen[c]){seen[c]=1;out.push(c)}});return out.sort()}
function fillBestSelects(){var f=document.getElementById("bestFrom"),tt=document.getElementById("bestTo");if(!f||!tt)return;var fv=f.value||"Dhaka",tv=tt.value||"Chattogram";var cs=cityListAll();f.innerHTML=cs.map(function(c){return "<option"+(c===fv?" selected":"")+">"+c+"</option>"}).join("");tt.innerHTML=cs.map(function(c){return "<option"+(c===tv?" selected":"")+">"+c+"</option>"}).join("")}
function computeBest(){var F=document.getElementById("bestFrom").value,T=document.getElementById("bestTo").value;var pref=(document.querySelector("input[name=bestPref]:checked")||{}).value||"balanced";var box=document.getElementById("bestOut");
var opts=SERVICES.filter(function(s){return s.cf===F&&s.ct===T});
if(!opts.length){box.innerHTML="<div class='err'>"+L("No reliable sample route data for "+F+" → "+T+" in this demo, so no “best” option is shown. Try the multi-transport Journey Planner on the Map page — it can combine services via a transfer point.","এই ডেমোতে "+F+" → "+T+" এর জন্য নির্ভরযোগ্য স্যাম্পল রুট ডেটা নেই, তাই কোনো “সেরা” অপশন দেখানো হচ্ছে না। ম্যাপ পেজের মাল্টি-ট্রান্সপোর্ট জার্নি প্ল্যানার চেষ্টা করুন — এটি ট্রান্সফার পয়েন্ট দিয়ে সার্ভিস যুক্ত করতে পারে।")+"</div>";return}
var fares=opts.map(function(s){return s.fare}),fmin=Math.min.apply(null,fares),fmax=Math.max.apply(null,fares);
var withDur=opts.filter(function(s){return s.dur>0}),tmin=withDur.length?Math.min.apply(null,withDur.map(function(s){return s.dur})):0,tmax=withDur.length?Math.max.apply(null,withDur.map(function(s){return s.dur})):0;
function scores(s){var fs=fmax===fmin?1:1-(s.fare-fmin)/(fmax-fmin);var ts=!s.dur||tmax===tmin?0.5:1-(s.dur-tmin)/(tmax-tmin);var rs=seedRating(s.key).avg/5;var trs=1-s.transfers*0.34;if(trs<0)trs=0;return{fs:fs,ts:ts,rs:rs,trs:trs,total:Math.round((0.35*fs+0.30*ts+0.25*rs+0.10*trs)*100)}}
var sorted=opts.slice();
if(pref==="cheap")sorted.sort(function(a,b){return a.fare-b.fare});
else if(pref==="fast")sorted.sort(function(a,b){return (a.dur||9999)-(b.dur||9999)});
else if(pref==="rating")sorted.sort(function(a,b){return seedRating(b.key).avg-seedRating(a.key).avg});
else sorted.sort(function(a,b){return scores(b).total-scores(a).total});
var w=sorted[0],ws=scores(w),why=[];
if(ws.fs>=0.99)why.push(L("lowest fare","সবচেয়ে কম ভাড়া"));else if(ws.fs>0.6)why.push(L("lower fare","তুলনামূলক কম ভাড়া"));
if(ws.ts>=0.99)why.push(L("shortest journey","সবচেয়ে কম সময়"));else if(ws.ts>0.6)why.push(L("faster journey","দ্রুততর যাত্রা"));
if(seedRating(w.key).avg>=4.4)why.push(L("highly rated","উচ্চ রেটিং"));
if(w.transfers===0)why.push(L("no transfers (direct)","ট্রান্সফার নেই (সরাসরি)"));
var html="<div class='rec'><strong>⭐ "+L("Best Suggestion: ","সেরা পরামর্শ: ")+esc(w.name)+"</strong> — "+esc(w.from)+" → "+esc(w.to)+"<br>"+L("Why: ","কারণ: ")+(why.length?why.join(" · "):L("best balance of fare, time and rating","ভাড়া, সময় ও রেটিংয়ের সেরা ভারসাম্য"))+"<br><span style='font-size:.88rem'>"+L("Balanced score = 35% fare + 30% time + 25% rating + 10% fewer transfers, each normalised 0–100 across the options below. Fares & times: sample data.","ভারসাম্য স্কোর = ৩৫% ভাড়া + ৩০% সময় + ২৫% রেটিং + ১০% কম ট্রান্সফার, প্রতিটি নিচের অপশনগুলোর মধ্যে ০–১০০ স্কেলে নরমালাইজ করা। ভাড়া ও সময়: স্যাম্পল ডেটা।")+"</span></div>";
html+="<div style='overflow-x:auto'><table><tr><th>"+L("Option","অপশন")+"</th><th>"+L("Fare","ভাড়া")+"</th><th>"+L("Time","সময়")+"</th><th>"+L("Rating","রেটিং")+"</th><th>"+L("Fare score","ভাড়া স্কোর")+"</th><th>"+L("Time score","সময় স্কোর")+"</th><th>"+L("Rating score","রেটিং স্কোর")+"</th><th>"+L("Balanced","ভারসাম্য")+"</th></tr>"+sorted.map(function(s){var sc=scores(s);return "<tr"+(s===w?" style='font-weight:700'":"")+"><td>"+s.icon+" "+esc(s.name)+"</td><td>"+s.fareLabel+"</td><td>"+(s.dur?fmtDur(s.dur):"—")+"</td><td>"+seedRating(s.key).avg.toFixed(1)+" ★</td><td>"+Math.round(sc.fs*100)+"</td><td>"+Math.round(sc.ts*100)+"</td><td>"+Math.round(sc.rs*100)+"</td><td>"+sc.total+"</td></tr>"}).join("")+"</table></div>";
html+=sorted.map(svcCard).join("");
box.innerHTML=html}
