function msgHtml(m){var inner=esc(m.text);if(m.type==="loc")inner="📍 "+esc(m.text)+"<br><a target='_blank' rel='noopener' href='"+m.link+"'>"+L("Open in Maps ↗","ম্যাপে খুলুন ↗")+"</a>";if(m.type==="file")inner="📎 "+esc(m.text)+" <span style='opacity:.8'>("+L("not uploaded — demo","আপলোড হয়নি — ডেমো")+")</span>";
return "<div class='msg "+m.from+"'>"+inner+"<small>"+m.time+(m.from==="me"?" · ✓✓ "+(m.status||"Seen")+" ("+L("simulated","সিমুলেটেড")+")":"")+"</small></div>"}
function renderThread(){var c=CHATS.filter(function(x){return x.id===curChat})[0];var box=document.getElementById("chatBox");if(!c||!box)return;var blocked=blockedChats[c.id];
box.innerHTML="<div style='display:flex;align-items:center;gap:10px;flex-wrap:wrap'><span class='cav'>"+esc(c.name.charAt(0))+"</span><strong style='font-size:1.05rem'>"+esc(c.name)+"</strong><span style='margin-left:auto;display:flex;gap:6px'><button class='btn small ghost' onclick='reportChat()'>"+L("Report","রিপোর্ট")+"</button><button class='btn small ghost' onclick='blockChat()'>"+(blocked?L("Unblock","আনব্লক"):L("Block","ব্লক"))+"</button></span></div><div id='chatNote' style='margin-top:8px'></div>"
+"<div class='thread' id='threadBox'>"+c.msgs.map(msgHtml).join("")+"</div>"
+(blocked?"<div class='notice'>"+L("You blocked this user (simulated). Unblock to send messages.","আপনি এই ব্যবহারকারীকে ব্লক করেছেন (সিমুলেটেড)। মেসেজ পাঠাতে আনব্লক করুন।")+"</div>"
:"<div style='display:flex;gap:6px;flex-wrap:wrap;margin-top:8px'><button class='btn small ghost' onclick=\"chatAttach('photo')\">📷 "+L("Photo","ছবি")+"</button><button class='btn small ghost' onclick=\"chatAttach('video')\">🎬 "+L("Video","ভিডিও")+"</button><button class='btn small ghost' onclick=\"chatAttach('file')\">📎 "+L("File","ফাইল")+"</button><button class='btn small ghost' onclick=\"chatAttach('location')\">📍 "+L("Location","লোকেশন")+"</button></div><div style='display:flex;gap:8px;margin-top:8px'><input id='chatInput' placeholder='"+L("Type a message…","মেসেজ লিখুন…")+"' onkeydown=\"if(event.key==='Enter'){event.preventDefault();sendChat()}\"><button class='btn' onclick='sendChat()'>"+L("Send","পাঠান")+"</button></div>");
var tb=document.getElementById("threadBox");if(tb)tb.scrollTop=tb.scrollHeight}
function pushMsg(cid,m){var c=CHATS.filter(function(x){return x.id===cid})[0];c.msgs.push(m);renderThread();renderChatList()}
function sendChat(){var inp=document.getElementById("chatInput");var v=inp.value.trim();if(!v)return;var cid=curChat;pushMsg(cid,{from:"me",type:"text",text:v,time:nowT(),status:"Seen"});
setTimeout(function(){if(curChat===cid)pushMsg(cid,{from:"them",type:"text",text:L("Thanks! (sample auto-reply — chat is simulated)","ধন্যবাদ! (স্যাম্পল অটো-রিপ্লাই — চ্যাট সিমুলেটেড)"),time:nowT(),status:"Seen"})},900)}
function chatAttach(kind){if(!curChat||blockedChats[curChat])return;
if(kind==="file"){var inp=document.createElement("input");inp.type="file";inp.onchange=function(){var f=inp.files&&inp.files[0];if(f)pushMsg(curChat,{from:"me",type:"file",text:f.name+" · "+Math.max(1,Math.round(f.size/1024))+" KB",time:nowT(),status:"Seen"})};inp.click();return}
if(kind==="location"){pushMsg(curChat,{from:"me",type:"loc",text:L("Shared location (sample) — Dhaka","শেয়ার করা লোকেশন (স্যাম্পল) — ঢাকা"),link:"https://www.google.com/maps/search/?api=1&query=Dhaka",time:nowT(),status:"Seen"});return}
pushMsg(curChat,{from:"me",type:kind,text:kind==="photo"?"📷 "+L("Photo (sample — not uploaded)","ছবি (স্যাম্পল — আপলোড হয়নি)"):"🎬 "+L("Video (sample — not uploaded)","ভিডিও (স্যাম্পল — আপলোড হয়নি)"),time:nowT(),status:"Seen"})}
function blockChat(){blockedChats[curChat]=!blockedChats[curChat];renderThread()}
function reportChat(){var n=document.getElementById("chatNote");if(n)n.innerHTML="<div class='success'>"+L("Reported (simulated). Nothing was sent anywhere.","রিপোর্ট করা হয়েছে (সিমুলেটেড)। কোথাও কিছু পাঠানো হয়নি।")+"</div>"}
/* --- Profile, auth, QR (all simulated, in-session only) --- */
var profileUser=null,registeredUser=null,pendingReg=null,profTab="info",settingsObj={notif:true,pub:false,loc:false},qrBig=false;
function newId(){var c="ABCDEFGHJKMNPQRSTUVWXYZ23456789",s="";for(var i=0;i<8;i++)s+=c[Math.floor(Math.random()*c.length)];return "JS-"+s}
function validMobile(m){return /^01[3-9]\d{8}$/.test(m||"")}
function updateAvatar(){var b=document.getElementById("avatarBtn");if(b)b.textContent=profileUser?profileUser.name.charAt(0).toUpperCase():"👤"}
function renderPMenu(){var m=document.getElementById("pmenu");if(!m)return;
if(!profileUser){m.innerHTML="<button onclick=\"hidePMenu();go('auth')\">"+L("Login / Register","লগইন / রেজিস্টার")+"</button><button onclick=\"hidePMenu();go('about')\">"+L("About","সম্পর্কে")+"</button>";return}
m.innerHTML="<button onclick=\"hidePMenu();profTab='info';go('profile')\">👤 "+L("My Profile","আমার প্রোফাইল")+"</button><button onclick=\"hidePMenu();profTab='info';go('profile')\">"+L("Personal Information","ব্যক্তিগত তথ্য")+"</button><button onclick=\"hidePMenu();profTab='qr';go('profile')\">"+L("My QR Code","আমার QR কোড")+"</button><button onclick=\"hidePMenu();profTab='pass';go('profile')\">"+L("Change Password","পাসওয়ার্ড বদলান")+"</button><button onclick=\"hidePMenu();profTab='settings';go('profile')\">"+L("Settings","সেটিংস")+"</button><button onclick='doLogout()'>"+L("Logout","লগআউট")+"</button>"}
function toggleProfileMenu(e){e.stopPropagation();renderPMenu();document.getElementById("pmenu").classList.toggle("on")}
function hidePMenu(){var m=document.getElementById("pmenu");if(m)m.classList.remove("on")}
document.addEventListener("click",function(e){var pm=document.getElementById("pmenu");if(pm&&!pm.contains(e.target))pm.classList.remove("on")});
function doLogout(){profileUser=null;updateAvatar();hidePMenu();go("home")}
function authErr(html){document.getElementById("authMsg").innerHTML=html?"<div class='err'>"+html+"</div>":""}
function submitRegister(e){e.preventDefault();var name=document.getElementById("rName").value.trim(),mob=document.getElementById("rMobile").value.trim(),dob=document.getElementById("rDob").value,gen=document.getElementById("rGender").value,p1=document.getElementById("rPass").value,p2=document.getElementById("rPass2").value;
if(!name)return authErr(L("Please enter your full name.","আপনার পুরো নাম লিখুন।"));
if(!validMobile(mob))return authErr(L("Enter a valid Bangladeshi mobile number (11 digits, starting 01).","সঠিক বাংলাদেশি মোবাইল নম্বর লিখুন (১১ সংখ্যা, 01 দিয়ে শুরু)।"));
if(!dob)return authErr(L("Please enter your date of birth.","জন্ম তারিখ দিন।"));
if(p1.length<6)return authErr(L("Password must be at least 6 characters.","পাসওয়ার্ড কমপক্ষে ৬ অক্ষরের হতে হবে।"));
if(p1!==p2)return authErr(L("Passwords do not match.","পাসওয়ার্ড মিলছে না।"));
authErr("");pendingReg={name:name,mobile:mob,dob:dob,gender:gen};document.getElementById("otpBox").style.display="block";document.getElementById("rOtp").focus()}
function verifyOtp(){var v=document.getElementById("rOtp").value.trim();if(!/^\d{4}$/.test(v)){authErr(L("Enter the 4-digit demo OTP.","৪ সংখ্যার ডেমো OTP লিখুন।"));return}
profileUser={name:pendingReg.name,mobile:pendingReg.mobile,dob:pendingReg.dob,gender:pendingReg.gender,id:newId()};registeredUser=profileUser;updateAvatar();
document.getElementById("authMsg").innerHTML="<div class='success'>"+L("Account created (simulated) with a unique QR code. Nothing was saved on a server.","অ্যাকাউন্ট তৈরি হয়েছে (সিমুলেটেড), অনন্য QR কোডসহ। সার্ভারে কিছু সংরক্ষিত হয়নি।")+"</div>";profTab="qr";go("profile")}
function submitLogin(e){e.preventDefault();var mob=document.getElementById("lMobile").value.trim(),p=document.getElementById("lPass").value;
if(!validMobile(mob))return authErr(L("Enter a valid Bangladeshi mobile number (11 digits, starting 01).","সঠিক বাংলাদেশি মোবাইল নম্বর লিখুন (১১ সংখ্যা, 01 দিয়ে শুরু)।"));
if(p.length<6)return authErr(L("Password must be at least 6 characters.","পাসওয়ার্ড কমপক্ষে ৬ অক্ষরের হতে হবে।"));
authErr("");if(registeredUser&&registeredUser.mobile===mob)profileUser=registeredUser;else profileUser={name:"Demo Guest",mobile:mob,dob:"",gender:"",id:newId()};updateAvatar();go("profile")}
function forgotPw(){document.getElementById("forgotOut").innerHTML="<div class='notice' style='margin-top:10px'>"+L("Password recovery is simulated in this prototype — no SMS or email is sent. In the production version this would send a secure reset code to your mobile.","পাসওয়ার্ড পুনরুদ্ধার এই প্রোটোটাইপে সিমুলেটেড — কোনো SMS বা ইমেইল পাঠানো হয় না। প্রোডাকশন সংস্করণে এটি আপনার মোবাইলে নিরাপদ রিসেট কোড পাঠাবে।")+"</div>"}
function setProfTab(tp){profTab=tp;renderProfile()}
function renderProfile(){var box=document.getElementById("profileBox");if(!box)return;
if(!profileUser){box.innerHTML="<div class='card' style='padding:22px;text-align:center'><h3>"+L("You are not logged in","আপনি লগইন করেননি")+"</h3><p style='color:var(--muted)'>"+L("Login or register (simulated) to see your profile, settings and unique QR code.","আপনার প্রোফাইল, সেটিংস ও অনন্য QR কোড দেখতে লগইন বা রেজিস্টার করুন (সিমুলেটেড)।")+"</p><button class='btn' onclick=\"go('auth')\">"+L("Login / Register","লগইন / রেজিস্টার")+"</button></div>";return}
var u=profileUser;var tabs=[["info",L("Personal Information","ব্যক্তিগত তথ্য")],["qr",L("My QR Code","আমার QR কোড")],["pass",L("Change Password","পাসওয়ার্ড বদলান")],["settings",L("Settings","সেটিংস")]];
var html="<div class='card' style='padding:18px'><div style='display:flex;gap:12px;align-items:center;flex-wrap:wrap'><span class='cav' style='width:56px;height:56px;font-size:1.4rem'>"+esc(u.name.charAt(0).toUpperCase())+"</span><div><strong style='font-size:1.2rem'>"+esc(u.name)+"</strong><div style='color:var(--muted)'>"+L("Public ID","পাবলিক আইডি")+": <strong>"+u.id+"</strong> · "+L("Mobile","মোবাইল")+": "+esc(u.mobile)+"</div></div></div>"
+"<div class='tabs' style='margin-top:16px'>"+tabs.map(function(x){return "<button class='"+(profTab===x[0]?"on":"")+"' onclick=\"setProfTab('"+x[0]+"')\">"+x[1]+"</button>"}).join("")+"</div><div id='profBody'></div></div>";
box.innerHTML=html;var body=document.getElementById("profBody");
if(profTab==="info"){body.innerHTML="<div><label for='pEditName'>"+L("Full name","পুরো নাম")+"</label><input id='pEditName' value='"+esc(u.name)+"'></div><div style='margin-top:10px'><label>"+L("Mobile number","মোবাইল নম্বর")+"</label><input value='"+esc(u.mobile)+"' disabled></div><div style='margin-top:10px'><label for='pEditDob'>"+L("Date of birth","জন্ম তারিখ")+"</label><input id='pEditDob' type='date' value='"+esc(u.dob||"")+"'></div><div style='margin-top:10px'><label for='pEditGender'>"+L("Gender","লিঙ্গ")+"</label><select id='pEditGender'><option"+(u.gender==="Female"?" selected":"")+">Female</option><option"+(u.gender==="Male"?" selected":"")+">Male</option><option"+(u.gender==="Other"?" selected":"")+">Other</option><option"+(u.gender==="Prefer not to say"?" selected":"")+">Prefer not to say</option></select></div><div style='margin-top:10px'><label for='pPhoto'>"+L("Profile picture","প্রোফাইল ছবি")+"</label><input id='pPhoto' type='file' accept='image/*' onchange='photoNote()'><div id='photoOut' style='margin-top:6px'></div></div><div id='profMsg' style='margin-top:10px'></div><button class='btn' style='margin-top:10px' onclick='saveProfile()'>"+L("Save changes (this session)","পরিবর্তন সংরক্ষণ (এই সেশনে)")+"</button><p style='color:var(--muted);font-size:.88rem'>"+L("Only your name and public ID are ever shown to other users, and only if you turn on “Public profile” in Settings.","অন্য ব্যবহারকারীদের শুধু আপনার নাম ও পাবলিক আইডি দেখানো হয়, তাও শুধু সেটিংসে “পাবলিক প্রোফাইল” চালু করলে।")+"</p>"}
else if(profTab==="qr"){body.innerHTML="<div class='qrbox"+(qrBig?" big":"")+"' id='qrWrap'><div id='qrBox'></div><p style='margin:10px 0 2px'>"+L("Public ID","পাবলিক আইডি")+": <strong>"+u.id+"</strong></p><p style='color:var(--muted);font-size:.88rem;margin:0'>"+L("This QR encodes only your opaque public ID — never your password, OTP, mobile number or other private details. Scanning it would show only the public profile information you allow.","এই QR-এ শুধু আপনার অস্বচ্ছ পাবলিক আইডি থাকে — কখনো পাসওয়ার্ড, OTP, মোবাইল নম্বর বা অন্য ব্যক্তিগত তথ্য নয়। স্ক্যান করলে শুধু আপনার অনুমোদিত পাবলিক প্রোফাইল তথ্যই দেখা যাবে।")+"</p><p style='display:flex;gap:8px;flex-wrap:wrap;justify-content:center'><button class='btn small' onclick='toggleQrBig()'>"+(qrBig?L("Shrink","ছোট করুন"):L("Enlarge","বড় করুন"))+"</button><button class='btn small ghost' onclick='downloadQR()'>"+L("Download QR","QR ডাউনলোড")+"</button><button class='btn small ghost' onclick='regenQR()'>"+L("Regenerate ID","নতুন আইডি তৈরি")+"</button></p><div id='qrMsg'></div></div>";drawQR()}
else if(profTab==="pass"){body.innerHTML="<div><label for='pwCur'>"+L("Current password","বর্তমান পাসওয়ার্ড")+"</label><input id='pwCur' type='password'></div><div style='margin-top:10px'><label for='pwNew'>"+L("New password","নতুন পাসওয়ার্ড")+"</label><input id='pwNew' type='password'></div><div style='margin-top:10px'><label for='pwNew2'>"+L("Confirm new password","নতুন পাসওয়ার্ড নিশ্চিত করুন")+"</label><input id='pwNew2' type='password'></div><div id='pwMsg' style='margin-top:10px'></div><button class='btn' style='margin-top:10px' onclick='changePw()'>"+L("Change password (simulated)","পাসওয়ার্ড বদলান (সিমুলেটেড)")+"</button>"}
else{body.innerHTML="<p style='display:flex;gap:8px;flex-wrap:wrap;align-items:center'><span style='min-width:210px'>"+L("Notifications","নোটিফিকেশন")+"</span><button class='tgl"+(settingsObj.notif?" on":"")+"' onclick='flipSetting(\"notif\")'>"+(settingsObj.notif?L("On","চালু"):L("Off","বন্ধ"))+"</button></p><p style='display:flex;gap:8px;flex-wrap:wrap;align-items:center'><span style='min-width:210px'>"+L("Public profile (name + ID visible to others)","পাবলিক প্রোফাইল (নাম + আইডি অন্যরা দেখতে পাবে)")+"</span><button class='tgl"+(settingsObj.pub?" on":"")+"' onclick='flipSetting(\"pub\")'>"+(settingsObj.pub?L("On","চালু"):L("Off","বন্ধ"))+"</button></p><p style='display:flex;gap:8px;flex-wrap:wrap;align-items:center'><span style='min-width:210px'>"+L("Location sharing in chat","চ্যাটে লোকেশন শেয়ার")+"</span><button class='tgl"+(settingsObj.loc?" on":"")+"' onclick='flipSetting(\"loc\")'>"+(settingsObj.loc?L("On","চালু"):L("Off","বন্ধ"))+"</button></p><p style='color:var(--muted);font-size:.88rem'>"+L("Settings apply to this browser session only in the prototype.","প্রোটোটাইপে সেটিংস শুধু এই ব্রাউজার সেশনে প্রযোজ্য।")+"</p>"}}
function photoNote(){var f=document.getElementById("pPhoto").files[0];document.getElementById("photoOut").innerHTML="<span class='chip'>"+esc(f?f.name:"")+"</span> <span style='color:var(--muted);font-size:.86rem'>"+L("Photo upload is simulated — the picture is not stored anywhere.","ছবি আপলোড সিমুলেটেড — ছবি কোথাও সংরক্ষিত হয় না।")+"</span>"}
function saveProfile(){profileUser.name=document.getElementById("pEditName").value.trim()||profileUser.name;profileUser.dob=document.getElementById("pEditDob").value;profileUser.gender=document.getElementById("pEditGender").value;updateAvatar();document.getElementById("profMsg").innerHTML="<div class='success'>"+L("Saved for this session.","এই সেশনের জন্য সংরক্ষিত হয়েছে।")+"</div>"}
function changePw(){var a=document.getElementById("pwNew").value,b=document.getElementById("pwNew2").value,m=document.getElementById("pwMsg");
if(a.length<6){m.innerHTML="<div class='err'>"+L("New password must be at least 6 characters.","নতুন পাসওয়ার্ড কমপক্ষে ৬ অক্ষরের হতে হবে।")+"</div>";return}
if(a!==b){m.innerHTML="<div class='err'>"+L("Passwords do not match.","পাসওয়ার্ড মিলছে না।")+"</div>";return}
m.innerHTML="<div class='success'>"+L("Password changed (simulated). Passwords are never stored or displayed in this prototype.","পাসওয়ার্ড বদলানো হয়েছে (সিমুলেটেড)। এই প্রোটোটাইপে পাসওয়ার্ড কখনো সংরক্ষণ বা দেখানো হয় না।")+"</div>"}
function flipSetting(k){settingsObj[k]=!settingsObj[k];renderProfile()}
function drawQR(){var box=document.getElementById("qrBox");if(!box||!profileUser)return;var text="jatriseba:user:"+profileUser.id;
try{if(typeof qrcode==="undefined")throw new Error("lib");var qr=qrcode(0,"M");qr.addData(text);qr.make();box.innerHTML=qr.createSvgTag(6,12)}catch(e){box.innerHTML="<div class='notice'>"+L("QR image could not be drawn (library offline). Your public ID is: ","QR ছবি আঁকা যায়নি (লাইব্রেরি অফলাইন)। আপনার পাবলিক আইডি: ")+"<strong>"+profileUser.id+"</strong></div>"}}
function toggleQrBig(){qrBig=!qrBig;renderProfile()}
function downloadQR(){var svg=document.querySelector("#qrBox svg");var msg=document.getElementById("qrMsg");if(!svg){if(msg)msg.innerHTML="<div class='err'>"+L("QR image is unavailable right now.","QR ছবি এখন unavailable।")+"</div>";return}
var blob=new Blob([new XMLSerializer().serializeToString(svg)],{type:"image/svg+xml"});var a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="jatriseba-my-qr.svg";document.body.appendChild(a);a.click();a.remove()}
function regenQR(){profileUser.id=newId();qrBig=false;renderProfile();var m=document.getElementById("qrMsg");if(m)m.innerHTML="<div class='success'>"+L("New public ID generated — the old QR is revoked in this demo session.","নতুন পাবলিক আইডি তৈরি হয়েছে — এই ডেমো সেশনে পুরনো QR বাতিল।")+"</div>"}
/* --- Home additions, about helpers --- */
var RECENT=[];
function noteRecent(q){if(RECENT.indexOf(q)<0){RECENT.unshift(q);RECENT=RECENT.slice(0,5)}renderRecent()}
function renderRecent(){var box=document.getElementById("recentBox");if(!box)return;
if(!RECENT.length){box.innerHTML="<p style='color:var(--muted)'>"+L("No searches yet in this session. Use the search bar at the very top — your recent searches will appear here. Saved/favorite routes appear in the full version after login.","এই সেশনে এখনো কোনো সার্চ হয়নি। একদম উপরের সার্চ বার ব্যবহার করুন — আপনার সাম্প্রতিক সার্চ এখানে দেখা যাবে। সংরক্ষিত/প্রিয় রুট পূর্ণ সংস্করণে লগইনের পর দেখা যায়।")+"</p>";return}
box.innerHTML="<p style='margin:0'>"+RECENT.map(function(q){return "<button class='chip' style='cursor:pointer;font:inherit' onclick=\"recentGo('"+q.replace(/'/g,"\\'")+"')\">"+esc(q)+"</button>"}).join(" ")+"</p>"}
function recentGo(q){window.scrollTo({top:0});document.getElementById("uQ").value=q;runUniversal()}
function buildCatGrid(){var box=document.getElementById("catGrid");if(!box)return;
box.innerHTML=CATMETA.slice(1).map(function(c){var n=SERVICES.filter(function(s){return s.type===c[0]}).length;var desc={bus:L("Intercity, Dhaka local and seat booking (sandbox)","আন্তঃনগর, ঢাকা লোকাল ও সিট বুকিং (স্যান্ডবক্স)"),train:L("Sample schedules, classes and fares","স্যাম্পল সময়সূচি, শ্রেণি ও ভাড়া"),launch:L("River routes from Sadarghat (sample)","সদরঘাট থেকে নদীপথের রুট (স্যাম্পল)"),bike:L("On-demand bike rides in Dhaka (sample)","ঢাকায় অন-ডিমান্ড বাইক রাইড (স্যাম্পল)"),car:L("Sedan & microbus rental with driver (sample)","ড্রাইভারসহ সেডান ও মাইক্রোবাস ভাড়া (স্যাম্পল)")}[c[0]];
return "<div class='card tile'><h3>"+c[1]+" "+L(c[2],c[0]==="bus"?"বাস":c[0]==="train"?"ট্রেন":c[0]==="launch"?"লঞ্চ":c[0]==="bike"?"বাইক":"প্রাইভেট কার")+"</h3><p>"+desc+" · "+n+" "+L("sample services","স্যাম্পল সার্ভিস")+"</p><p style='margin-top:10px'><button class='btn small' onclick=\"goCat('"+c[0]+"')\">"+L("Browse","দেখুন")+"</button></p></div>"}).join("")}
function renderPopSvc(){var box=document.getElementById("popSvc");if(!box)return;var top=SERVICES.slice().sort(function(a,b){return seedRating(b.key).avg-seedRating(a.key).avg}).slice(0,3);
box.innerHTML=top.map(function(s){return "<div class='card tile'><h3>"+s.icon+" "+esc(s.name)+"</h3><p>"+esc(s.from)+" → "+esc(s.to)+" · "+s.fareLabel+"</p><p style='margin-top:4px'>"+ratingLine(s.key)+"</p><p style='margin-top:8px'><button class='btn small' onclick=\"openService('"+s.key+"')\">"+L("Details","বিস্তারিত")+"</button></p></div>"}).join("")}
function goAbout(id){go("about");setTimeout(function(){var e=document.getElementById(id);if(e)e.scrollIntoView({block:"start"})},80)}
function submitReport(){var v=document.getElementById("repTxt").value.trim();var o=document.getElementById("repOut");if(!v){o.innerHTML="<div class='err'>"+L("Please describe what is incorrect first.","আগে কী ভুল তা লিখুন।")+"</div>";return}o.innerHTML="<div class='success'>"+L("Report noted (simulated): “","রিপোর্ট নোট করা হয়েছে (সিমুলেটেড): “")+esc(v)+L("” — nothing was sent anywhere in this prototype.","” — এই প্রোটোটাইপে কোথাও কিছু পাঠানো হয়নি।")+"</div>"}
/* --- Map: journey planner & service route --- */
var CITY_COORDS={"Dhaka":[23.8103,90.4125],"Chattogram":[22.3569,91.7832],"Sylhet":[24.9045,91.8699],"Khulna":[22.8456,89.5403],"Rajshahi":[24.3745,88.6042],"Cox's Bazar":[21.4272,92.0058],"Barishal":[22.7010,90.3535],"Cumilla":[23.4607,91.1809],"Panchagarh":[26.3411,88.5542],"Lalmonirhat":[25.9167,89.4500],"Chilahati":[26.3220,88.7460],"Dinajpur":[25.6217,88.6355],"Jashore":[23.1634,89.2182],"Bogura":[24.8510,89.3711],"Feni":[23.0159,91.3976],"Tangail":[24.2513,89.9163]};
var STOP_COORDS={};LOCAL.forEach(function(r){r.stops.forEach(function(s){STOP_COORDS[s[0]]=[s[1],s[2]]})});
function findCoord(q){if(!q)return null;q=q.trim().toLowerCase();var k;for(k in STOP_COORDS)if(k.toLowerCase().indexOf(q)>=0||q.indexOf(k.toLowerCase())>=0)return{label:k,pt:STOP_COORDS[k]};
for(var i=0;i<CITY_ALIAS.length;i++)for(var j=0;j<CITY_ALIAS[i][1].length;j++)if(q.indexOf(CITY_ALIAS[i][1][j])>=0&&CITY_COORDS[CITY_ALIAS[i][0]])return{label:CITY_ALIAS[i][0],pt:CITY_COORDS[CITY_ALIAS[i][0]]};
for(k in CITY_COORDS)if(k.toLowerCase()===q)return{label:k,pt:CITY_COORDS[k]};return null}
function findCityIn(q){if(!q)return null;q=q.toLowerCase();for(var i=0;i<CITY_ALIAS.length;i++)for(var j=0;j<CITY_ALIAS[i][1].length;j++)if(q.indexOf(CITY_ALIAS[i][1][j])>=0)return CITY_ALIAS[i][0];return null}
function stopRoutes(q){q=q.trim().toLowerCase();var out=[];LOCAL.forEach(function(r){if(r.stops.some(function(s){return s[0].toLowerCase().indexOf(q)>=0||q.indexOf(s[0].toLowerCase())>=0}))out.push(r)});return out}
function stopNameIn(r,q){q=q.trim().toLowerCase();var f=r.stops.filter(function(s){return s[0].toLowerCase().indexOf(q)>=0||q.indexOf(s[0].toLowerCase())>=0});return f.length?f[0][0]:null}
var map2Obj=null,map2Layer=null,plannerPts=null;
function drawPlannerMap(pts){var LF=window.__LF;var fb=document.getElementById("map2Fallback");
if(!pts||pts.length<1){if(!plannerPts){var a=findCoord(document.getElementById("mpFrom").value),b=findCoord(document.getElementById("mpTo").value);pts=[];if(a)pts.push(a);if(b)pts.push(b)}else pts=plannerPts}
if(!LF||!LF.map){if(fb)fb.style.display="block";return}
try{if(!map2Obj){map2Obj=LF.map("map2");var tiles=LF.tileLayer("https://tile.openstreetmap.org/{z}/{x}/{y}.png",{attribution:"© OpenStreetMap contributors"});tiles.on("tileerror",function(){if(fb)fb.style.display="block"});tiles.addTo(map2Obj)}
if(map2Layer)map2Obj.removeLayer(map2Layer);map2Layer=LF.layerGroup();
var latlngs=pts.map(function(p){return p.pt});
if(latlngs.length>1)LF.polyline(latlngs,{color:"#b7791f",weight:4,dashArray:"7 8"}).addTo(map2Layer);
pts.forEach(function(p){LF.marker(p.pt).addTo(map2Layer).bindPopup(p.label)});map2Layer.addTo(map2Obj);
if(latlngs.length>1)map2Obj.fitBounds(LF.latLngBounds(latlngs),{padding:[30,30]});else if(latlngs.length===1)map2Obj.setView(latlngs[0],12);
setTimeout(function(){map2Obj.invalidateSize()},150)}catch(e){if(fb)fb.style.display="block"}}
function viewServiceMap(key){var s=svcByKey(key);if(!s)return;go("mapview");plannerPts=null;
document.getElementById("mpFrom").value=s.from;document.getElementById("mpTo").value=s.to;
var pts=[];if(s.localId){var r=LOCAL.filter(function(x){return x.id===s.localId})[0];pts=r.stops.map(function(x){return{label:x[0],pt:[x[1],x[2]]}})}
else{var a=findCoord(s.cf||s.from),b=findCoord(s.ct||s.to);if(a)pts.push(a);s.stops.forEach(function(st){var c=findCoord(st);if(c&&(!a||c.label!==a.label)&&(!b||c.label!==b.label))pts.push(c)});if(b)pts.push(b)}
plannerPts=pts;
var out=document.getElementById("mpOut");out.innerHTML="<div class='card' style='padding:14px'><strong>"+s.icon+" "+esc(s.name)+"</strong> — "+esc(s.from)+" → "+esc(s.to)+"<br><span style='color:var(--muted)'>"+s.dep+(s.arr&&s.arr!=="—"?" → "+s.arr:"")+" · "+s.fareLabel+" · "+L("Route line is approximate: it connects the known boarding point, stops and destination only — the bus's exact road path and live position are not shown.","রুট লাইন আনুমানিক: এটি শুধু জানা বোর্ডিং পয়েন্ট, স্টপ ও গন্তব্য যুক্ত করে — বাসের সঠিক রাস্তার পথ ও লাইভ অবস্থান দেখানো হয় না।")+"</span><p style='display:flex;gap:8px;flex-wrap:wrap;margin:10px 0 0'><a class='btn small' style='text-decoration:none' target='_blank' rel='noopener' href='https://www.google.com/maps/dir/?api=1&origin="+encodeURIComponent(s.from)+"&destination="+encodeURIComponent(s.to)+"'>"+L("Get Directions ↗","দিকনির্দেশনা ↗")+"</a>"+(s.localId?"<button class='btn small ghost' onclick='showOnMap("+s.localId+")'>"+L("See full stop map above","উপরে পুরো স্টপ ম্যাপ দেখুন")+"</button>":"")+"</p></div>";
setTimeout(function(){drawPlannerMap(pts)},200)}
function useMyLocation(){var note=document.getElementById("mpLocNote");
if(!navigator.geolocation){note.innerHTML="<div class='err'>"+L("Geolocation is not available in this browser — type your starting point manually.","এই ব্রাউজারে জিওলোকেশন নেই — শুরুর জায়গা নিজে লিখুন।")+"</div>";return}
note.innerHTML="<div class='notice'>"+L("Asking your browser for location permission… it is used only to fill the starting point in this page.","ব্রাউজারের কাছে লোকেশন অনুমতি চাওয়া হচ্ছে… এটি শুধু এই পেজে শুরুর জায়গা পূরণে ব্যবহৃত হবে।")+"</div>";
navigator.geolocation.getCurrentPosition(function(pos){var la=pos.coords.latitude,lo=pos.coords.longitude,best=null,bd=1e9;
for(var k in STOP_COORDS){var p=STOP_COORDS[k],d=(p[0]-la)*(p[0]-la)+(p[1]-lo)*(p[1]-lo);if(d<bd){bd=d;best=k}}
if(best)document.getElementById("mpFrom").value=best;
note.innerHTML="<div class='success'>"+L("Your location (approx. "+la.toFixed(4)+", "+lo.toFixed(4)+") — nearest known stop in the sample data: ","আপনার লোকেশন (আনুমানিক "+la.toFixed(4)+", "+lo.toFixed(4)+") — স্যাম্পল ডেটায় সবচেয়ে কাছের জানা স্টপ: ")+"<strong>"+(best||"—")+"</strong>. "+L("Nothing was shared or stored.","কিছু শেয়ার বা সংরক্ষণ করা হয়নি।")+"</div>"},
function(){note.innerHTML="<div class='err'>"+L("Location permission was denied or unavailable — type your starting point manually.","লোকেশন অনুমতি দেওয়া হয়নি বা পাওয়া যায়নি — শুরুর জায়গা নিজে লিখুন।")+"</div>"},{timeout:8000})}
function segHtml(icon,txt,sub){return "<div class='seg'><span class='seg-ic'>"+icon+"</span><span><strong>"+txt+"</strong>"+(sub?"<br><span style='color:var(--muted);font-size:.88rem'>"+sub+"</span>":"")+"</span></div>"}
function planJourney(){var A=document.getElementById("mpFrom").value.trim(),B=document.getElementById("mpTo").value.trim(),out=document.getElementById("mpOut");plannerPts=null;
if(!A||!B){out.innerHTML="<div class='err'>"+L("Enter both a starting point and a destination.","শুরুর জায়গা ও গন্তব্য দুটোই লিখুন।")+"</div>";return}
var journeys=[];
var ra=stopRoutes(A),rb=stopRoutes(B);
if(ra.length&&rb.length){var direct=ra.filter(function(r){return rb.indexOf(r)>=0});
direct.forEach(function(r){var sa=stopNameIn(r,A),sb=stopNameIn(r,B);journeys.push({title:r.name,transfers:0,fare:r.fare,fareN:parseInt((r.fare.match(/\d+/g)||[0]).pop(),10)||0,dur:r.stops.length*7,segs:segHtml("🚶",L("Walk to ","হেঁটে যান ")+sa,"")+segHtml("🚌",r.name+" — "+r.from+" → "+r.to,L("Get down at ","নামুন ")+sb+" · "+L("fare ","ভাড়া ")+r.fare)+segHtml("🚶",L("Walk from ","হেঁটে যান ")+sb,L("to your final destination","আপনার চূড়ান্ত গন্তব্যে")),pts:[{label:sa,pt:STOP_COORDS[sa]},{label:sb,pt:STOP_COORDS[sb]}]})});
if(!journeys.length){outer:for(var i=0;i<ra.length;i++)for(var j=0;j<rb.length;j++){var common=ra[i].stops.map(function(s){return s[0]}).filter(function(n){return rb[j].stops.some(function(s){return s[0]===n})});if(common.length){var sa2=stopNameIn(ra[i],A),sb2=stopNameIn(rb[j],B);journeys.push({title:ra[i].name+" + "+rb[j].name,transfers:1,fare:ra[i].fare+" + "+rb[j].fare,fareN:0,dur:(ra[i].stops.length+rb[j].stops.length)*7,segs:segHtml("🚶",L("Walk to ","হেঁটে যান ")+sa2,"")+segHtml("🚌",ra[i].name,L("Ride to transfer point ","ট্রান্সফার পয়েন্টে যান ")+common[0])+segHtml("🔁",L("Change bus at ","বাস বদলান ")+common[0],"")+segHtml("🚌",rb[j].name,L("Ride to ","যান ")+sb2)+segHtml("🚶",L("Walk from ","হেঁটে যান ")+sb2,""),pts:[{label:sa2,pt:STOP_COORDS[sa2]},{label:common[0],pt:STOP_COORDS[common[0]]},{label:sb2,pt:STOP_COORDS[sb2]}]});break outer}}}}
if(!journeys.length){var ca=findCityIn(A),cb=findCityIn(B);
if(ca&&cb){var direct2=SERVICES.filter(function(s){return s.cf===ca&&s.ct===cb}).slice(0,3);
direct2.forEach(function(s){journeys.push({title:s.name,transfers:0,fare:s.fareLabel,fareN:s.fare,dur:s.dur,segs:segHtml("🚶",L("Go to boarding point: ","বোর্ডিং পয়েন্টে যান: ")+s.stops[0],"")+segHtml(s.icon,s.name+" — "+s.from+" → "+s.to,s.dep+" · "+s.fareLabel+(s.dur?" · "+fmtDur(s.dur):""))+segHtml("🚶",L("Walk from ","হেঁটে যান ")+s.stops[s.stops.length-1],L("to your final destination","আপনার চূড়ান্ত গন্তব্যে")),pts:null,svc:s})});
if(!journeys.length&&ca!=="Dhaka"&&cb!=="Dhaka"){var l1=SERVICES.filter(function(s){return s.cf===ca&&s.ct==="Dhaka"})[0],l2=SERVICES.filter(function(s){return s.cf==="Dhaka"&&s.ct===cb})[0];
if(l1&&l2)journeys.push({title:l1.name+" + "+l2.name,transfers:1,fare:l1.fareLabel+" + "+l2.fareLabel,fareN:l1.fare+l2.fare,dur:(l1.dur||0)+(l2.dur||0),segs:segHtml(l1.icon,l1.name+" — "+l1.from+" → Dhaka",l1.dep+" · "+l1.fareLabel)+segHtml("🔁",L("Transfer in Dhaka","ঢাকায় ট্রান্সফার"),"")+segHtml(l2.icon,l2.name+" — Dhaka → "+l2.to,l2.dep+" · "+l2.fareLabel),pts:null,svc:null})}}}
if(!journeys.length){out.innerHTML="<div class='card' style='padding:22px;text-align:center'><h3>"+L("No journey found in the sample data","স্যাম্পল ডেটায় কোনো যাত্রা পাওয়া যায়নি")+"</h3><p style='color:var(--muted)'>"+L("Try two Dhaka stops (e.g. Mirpur 10 → Sadarghat) or two cities (e.g. Dhaka → Sylhet). No route is invented when the sample data has none.","ঢাকার দুটি স্টপ (যেমন Mirpur 10 → Sadarghat) বা দুটি শহর (যেমন Dhaka → Sylhet) চেষ্টা করুন। স্যাম্পল ডেটায় রুট না থাকলে কোনো রুট বানানো হয় না।")+"</p></div>";return}
var cheapest=journeys.slice().sort(function(a,b){return (a.fareN||99999)-(b.fareN||99999)})[0];
var fastest=journeys.slice().sort(function(a,b){return (a.dur||9999)-(b.dur||9999)})[0];
var fewest=journeys.slice().sort(function(a,b){return a.transfers-b.transfers})[0];
out.innerHTML=journeys.map(function(jn){var tags=[];if(jn===cheapest&&jn.fareN)tags.push(L("Lowest fare","সবচেয়ে কম ভাড়া"));if(jn===fastest&&jn.dur)tags.push(L("Shortest time","সবচেয়ে কম সময়"));if(jn===fewest)tags.push(L("Fewest transfers","সবচেয়ে কম ট্রান্সফার"));
return "<div class='card' style='padding:16px;margin-bottom:12px'><div class='trip-head'><strong>"+esc(jn.title)+"</strong><span>"+tags.map(function(x){return "<span class='badge b-ver'>"+x+"</span>"}).join(" ")+"</span></div><div style='color:var(--muted);font-size:.9rem'>"+L("Total fare (sample): ","মোট ভাড়া (স্যাম্পল): ")+jn.fare+(jn.dur?" · "+L("Approx. duration: ","আনুমানিক সময়: ")+fmtDur(jn.dur):"")+" · "+L("Transfers: ","ট্রান্সফার: ")+jn.transfers+"</div>"+jn.segs+"</div>"}).join("")+"<p style='color:var(--muted);font-size:.88rem'>"+L("Recommended first: fewest transfers, then lower sample fare. All steps come from the sample dataset; exact bus road paths are not shown.","প্রথম সুপারিশ: সবচেয়ে কম ট্রান্সফার, তারপর কম স্যাম্পল ভাড়া। সব ধাপ স্যাম্পল ডেটাসেট থেকে; বাসের সঠিক রাস্তার পথ দেখানো হয় না।")+"</p>";
var pts=journeys[0].pts;if(!pts){var a2=findCoord(A),b2=findCoord(B);pts=[];if(a2)pts.push(a2);if(b2)pts.push(b2)}
plannerPts=pts;drawPlannerMap(pts)}
function renderNew(){buildCatGrid();renderPopSvc();renderRecent();fillBestSelects();renderCats();renderChatList();renderPMenu();updateAvatar();if(typeof renderDivisions==="function")renderDivisions();if(typeof renderTourSearch==="function")renderTourSearch()}
