var curDiv=null,curSight=null;
function goExplore(){go("home");setTimeout(function(){var e=document.getElementById("exploreSection");if(e)e.scrollIntoView({block:"start"})},90)}
function renderDivisions(){var box=document.getElementById("divGrid");if(!box)return;
box.innerHTML=DIVISIONS.map(function(d){return "<button type='button' class='div-card' onclick=\"openDivision('"+d.id+"')\" aria-label='"+esc(d.en)+"'><img src='"+d.img+"' alt='"+esc(d.cap)+"' loading='lazy' onerror=\"this.style.opacity=0\"><span class='dc-body'><h3>"+d.bn+"</h3><span class='dc-en'>"+d.en+"</span><p>"+TL(d.intro)+"</p><span class='dc-cta'>"+LB("ঘুরে দেখুন · Explore","Explore Division")+" →</span></span></button>"}).join("")}
function sightCard(d,s,idx){return "<article class='card sight-card'><img src='"+s.img+"' alt='"+esc(s.cap)+"' loading='lazy' onerror=\"this.style.display='none'\"><div class='sc-body'><span class='chip'>"+TL({en:TYPE_LBL[s.type][0],bn:TYPE_LBL[s.type][1]})+"</span> <span class='chip'>"+esc(s.dist.split("·")[0].trim())+"</span><h3>"+TL(s)+"</h3><p style='color:var(--muted);margin:4px 0 10px;font-size:.92rem'>"+TL(s.desc)+"</p><p style='display:flex;gap:8px;flex-wrap:wrap;margin:0'><button class='btn small' onclick=\"openSight('"+d.id+"',"+idx+")\">"+LB("বিস্তারিত দেখুন","Details")+"</button><a class='btn small ghost' style='text-decoration:none' target='_blank' rel='noopener' href='https://www.google.com/maps/search/?api=1&query="+encodeURIComponent(s.en+", Bangladesh")+"'>"+LB("ম্যাপে দেখুন","View on map")+" ↗</a></p></div></article>"}
function openDivision(id){curDiv=DIVISIONS.filter(function(d){return d.id===id})[0];if(!curDiv)return;renderDivision();go("division")}
function renderDivision(){var d=curDiv;if(!d)return;var box=document.getElementById("divBox");
box.innerHTML="<div class='div-hero'><img src='"+d.img+"' alt='"+esc(d.cap)+"' onerror=\"this.style.display='none'\"><div class='dh-body'><h2>"+d.bn+" · "+d.en+"</h2><p style='margin:6px 0 12px;max-width:640px'>"+TL(d.intro)+"</p><p style='display:flex;gap:8px;flex-wrap:wrap;margin:0'><a class='btn small' style='text-decoration:none;background:#fff;color:#004d38' href='#sightList'>"+LB("জনপ্রিয় স্থান দেখুন","See popular places")+"</a><button class='btn small ghost' style='background:rgba(255,255,255,.14);color:#fff;border-color:#fff' onclick=\"findTransportTo('"+d.city+"')\">"+LB("এই বিভাগে যাওয়ার পরিবহন খুঁজুন","Find transport to this division")+"</button><a class='btn small ghost' style='text-decoration:none;background:rgba(255,255,255,.14);color:#fff;border-color:#fff' target='_blank' rel='noopener' href='https://www.google.com/maps/search/?api=1&query="+encodeURIComponent(d.en+", Bangladesh")+"'>"+LB("ম্যাপে দেখুন","View on map")+" ↗</a></p></div></div>"
+"<p class='img-credit'>"+LB("ছবি: ","Photo: ")+esc(d.cap)+". "+LB("ছবিগুলো নামকরা স্থানের প্রকৃত প্রকাশিত ছবি; কয়েকটি কার্ডে একই বিভাগের প্রতিনিধিত্বমূলক ছবি ব্যবহৃত হয়েছে, যা বিস্তারিত পেজে সততার সাথে উল্লেখ করা আছে।","Photos are real published photographs of the named places; a few attraction cards reuse a representative photo of the same division, captioned honestly in the detail view.")+"</p>"
+"<h3 id='sightList' style='margin:20px 0 10px'>"+LB("জনপ্রিয় স্থান ও দর্শনীয় জায়গা","Popular places & attractions")+" ("+d.sights.length+")</h3><div class='sight-grid'>"+d.sights.map(function(s,i){return sightCard(d,s,i)}).join("")+"</div>"
+"<div class='card' style='padding:16px;margin-top:16px'><h3 style='margin-top:0'>"+LB("কীভাবে যাবেন — Jatri Seba পরিবহন","How to get there — Jatri Seba transport")+"</h3><p style='color:var(--muted)'>"+LB("নিচের বোতামে এই বিভাগের প্রধান শহরে ("+d.city+") যাওয়ার স্যাম্পল বাস/ট্রেন/লঞ্চ অপশন খুঁজুন। সময়সূচি ও ভাড়া স্যাম্পল ডেটা — আসল যাত্রার আগে যাচাই করুন। রোড-ডিরেকশন আর বাসের প্রকৃত রুট এক নয়; ম্যাপে রুট আনুমানিক হিসেবে লেবেল করা থাকে।","Use the button to search sample bus/train/launch options to this division's main city ("+d.city+"). Schedules and fares are sample data — verify before real travel. Road directions are not the same as a bus's real operating route; map lines are labelled approximate.")+"</p><p style='display:flex;gap:8px;flex-wrap:wrap'><button class='btn small' onclick=\"findTransportTo('"+d.city+"')\">"+LB("এই স্থানে যাওয়ার বাস খুঁজুন","Find buses to this place")+"</button><button class='btn small ghost' onclick='go(\"mapview\")'>"+LB("রুট দেখুন (ম্যাপ)","View routes (Map)")+"</button></p></div>"}
function backToDivision(){if(curDiv){renderDivision();go("division")}else goExplore()}
function openSight(divId,idx){var d=DIVISIONS.filter(function(x){return x.id===divId})[0];if(!d)return;var s=d.sights[idx];if(!s)return;curDiv=d;curSight=s;renderSight();go("sight")}
function renderSight(){var d=curDiv,s=curSight;if(!d||!s)return;var box=document.getElementById("sightBox");
var nearby=d.sights.filter(function(x){return x!==s}).slice(0,3);
box.innerHTML="<article class='card' style='padding:18px'><img class='sight-hero-img' src='"+s.img+"' alt='"+esc(s.cap)+"' onerror=\"this.style.display='none'\"><p class='img-credit'>"+LB("ছবিতে: ","Photo shows: ")+esc(s.cap)+"</p>"
+"<h2 style='margin:10px 0 2px'>"+TL(s)+"</h2><p style='color:var(--muted);margin:0 0 10px'>"+esc(s.dist)+" · "+d.bn+" ("+d.en+") · "+TL({en:TYPE_LBL[s.type][0],bn:TYPE_LBL[s.type][1]})+"</p>"
+"<p>"+TL(s.desc)+"</p><dl class='kv'><dt>"+LB("কেন জনপ্রিয়","Why popular")+"</dt><dd>"+TL(s.why)+"</dd><dt>"+LB("সেরা সময়","Best time to visit")+"</dt><dd>"+esc(s.best)+"</dd><dt>"+LB("খোলার সময় / প্রবেশ ফি","Opening hours / entry fee")+"</dt><dd>"+LB("এই প্রোটোটাইপে যাচাইকৃত তথ্য নেই — যাওয়ার আগে স্থানীয়ভাবে জেনে নিন।","Not verified in this prototype — please check locally before visiting.")+"</dd><dt>"+LB("আনুমানিক খরচ / যাত্রার সময়","Estimated cost / travel time")+"</dt><dd>"+LB("নির্ভরযোগ্য সোর্স ছাড়া দেখানো হয়নি। নিচে পরিবহন সার্চে স্যাম্পল ভাড়া ও সময় দেখুন।","Not shown without a reliable source. See sample fares and times in the transport search below.")+"</dd></dl>"
+"<h3>"+LB("কীভাবে যাবেন","How to get there")+"</h3><p style='color:var(--muted)'>"+LB("Jatri Seba-তে "+d.city+" পর্যন্ত স্যাম্পল বাস, ট্রেন ও লঞ্চ অপশন আছে। সেখান থেকে স্থানীয় পরিবহনে গন্তব্যে যাওয়া যায় — বিস্তারিত স্থানীয়ভাবে যাচাই করুন। সাধারণ রোড-ডিরেকশন বাসের প্রকৃত অপারেটিং রুট নয়।","Jatri Seba lists sample bus, train and launch options to "+d.city+"; local transport continues from there — verify details locally. General road directions are not a bus's real operating route.")+"</p>"
+"<p style='display:flex;gap:8px;flex-wrap:wrap'><button class='btn small' onclick=\"findTransportTo('"+d.city+"')\">"+LB("এই স্থানে যাওয়ার বাস খুঁজুন","Find transport to this place")+"</button><a class='btn small ghost' style='text-decoration:none' target='_blank' rel='noopener' href='https://www.google.com/maps/dir/?api=1&destination="+encodeURIComponent(s.en+", "+s.dist.split("·")[0].trim()+", Bangladesh")+"'>"+LB("দিকনির্দেশনা (Google Maps) ↗","Directions (Google Maps) ↗")+"</a><a class='btn small ghost' style='text-decoration:none' target='_blank' rel='noopener' href='https://www.google.com/maps/search/?api=1&query="+encodeURIComponent(s.en+", Bangladesh")+"'>"+LB("ম্যাপে দেখুন ↗","View on map ↗")+"</a><button class='btn small ghost' onclick='goAbout(\"about-report\")'>"+LB("ভুল তথ্য রিপোর্ট করুন","Report incorrect information")+"</button></p></article>"
+(nearby.length?"<h3 style='margin:20px 0 10px'>"+LB("কাছাকাছি দর্শনীয় স্থান","Nearby attractions")+"</h3><div class='sight-grid'>"+nearby.map(function(x){return sightCard(d,x,d.sights.indexOf(x))}).join("")+"</div>":"")}
function findTransportTo(city){go("services");fillBestSelects();var f=document.getElementById("bestFrom"),tt=document.getElementById("bestTo"),box=document.getElementById("bestOut");if(cityListAll().indexOf(city)>=0){if(f)f.value="Dhaka";if(tt)tt.value=city;computeBest()}else if(box){box.innerHTML="<div class='notice'>"+LB("এই প্রোটোটাইপের স্যাম্পল ডেটায় "+city+" যাওয়ার সরাসরি সার্ভিস এখনো নেই — কোনো রুট বানানো হয়নি। Map পেজের Journey Planner-এ ট্রান্সফারসহ বিকল্প দেখুন, অথবা Services তালিকা থেকে কাছের শহর বেছে নিন।","No direct sample service to "+city+" exists in this prototype's dataset yet — no route has been invented. Try the Map page Journey Planner for transfer options, or pick a nearby city from the Services list.")+"</div>"}window.scrollTo({top:0})}
function renderTourSearch(){var box=document.getElementById("tourResults");if(!box)return;var q=((document.getElementById("tourQ")||{}).value||"").trim().toLowerCase();var tp=(document.getElementById("tourType")||{}).value||"";
var out=[];
DIVISIONS.forEach(function(d){d.sights.forEach(function(s){if(tp&&s.type!==tp)return;if(q&&(s.en+" "+s.bn+" "+s.dist+" "+d.en+" "+d.bn).toLowerCase().indexOf(q)<0)return;out.push([d,s])})});
if(!q&&!tp){box.innerHTML="";return}
if(!out.length){box.innerHTML="<div class='card' style='padding:20px;text-align:center'><h3>"+LB("কিছু পাওয়া যায়নি","Nothing found")+"</h3><p style='color:var(--muted)'>"+LB("অন্য নাম বা ধরন চেষ্টা করুন — যেমন Cox's Bazar, Sylhet, beach, মসজিদ।","Try another name or type — e.g. Cox's Bazar, Sylhet, beach.")+"</p></div>";return}
box.innerHTML="<div class='sight-grid'>"+out.slice(0,12).map(function(p){return sightCard(p[0],p[1],p[0].sights.indexOf(p[1]))}).join("")+"</div>"}
renderNew();
toggleLang();
